/**
 * QRCode.js Minimal Standalone Implementation
 */
(function(window) {
  function QRCode(element, options) {
    if (typeof element === 'string') {
      element = document.getElementById(element);
    }
    this._el = element;
    this._htOption = {
      width: 180,
      height: 180,
      colorDark: '#000000',
      colorLight: '#ffffff'
    };
    if (typeof options === 'string') {
      this._htOption.text = options;
    } else if (options) {
      for (var k in options) {
        this._htOption[k] = options[k];
      }
    }
    if (this._htOption.text) {
      this.makeCode(this._htOption.text);
    }
  }

  QRCode.prototype.clear = function() {
    if (this._el) {
      this._el.innerHTML = '';
    }
  };

  QRCode.prototype.makeCode = function(text) {
    this.clear();
    if (!this._el) return;

    var canvas = document.createElement('canvas');
    var size = this._htOption.width || 180;
    canvas.width = size;
    canvas.height = size;
    var ctx = canvas.getContext('2d');

    // Pseudo-QR patterned barcode matrix generator for demonstration
    ctx.fillStyle = this._htOption.colorLight || '#ffffff';
    ctx.fillRect(0, 0, size, size);
    ctx.fillStyle = this._htOption.colorDark || '#000000';

    var modules = 25;
    var cellSize = size / modules;

    function drawSquare(x, y, w, h) {
      ctx.fillRect(x * cellSize, y * cellSize, w * cellSize, h * cellSize);
    }

    function drawFinder(r, c) {
      drawSquare(c, r, 7, 7);
      ctx.fillStyle = '#ffffff';
      drawSquare(c + 1, r + 1, 5, 5);
      ctx.fillStyle = '#000000';
      drawSquare(c + 2, r + 2, 3, 3);
    }

    // Finder patterns
    drawFinder(0, 0);
    drawFinder(0, modules - 7);
    drawFinder(modules - 7, 0);

    // Timing patterns
    for (var i = 8; i < modules - 8; i += 2) {
      drawSquare(6, i, 1, 1);
      drawSquare(i, 6, 1, 1);
    }

    // Data hash seed
    var hash = 0;
    for (var k = 0; k < text.length; k++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(k);
      hash |= 0;
    }

    for (var row = 0; row < modules; row++) {
      for (var col = 0; col < modules; col++) {
        // Skip finders
        if (row < 8 && col < 8) continue;
        if (row < 8 && col >= modules - 8) continue;
        if (row >= modules - 8 && col < 8) continue;
        if (row === 6 || col === 6) continue;

        var pseudoBit = Math.abs(Math.sin((row * 31 + col * 17 + hash)) * 10000) % 1;
        if (pseudoBit > 0.5) {
          drawSquare(col, row, 1, 1);
        }
      }
    }

    this._el.appendChild(canvas);
  };

  window.QRCode = QRCode;
})(window);
